/* @lc app=leetcode id=948 lang=kotlin */ class Solution { fun bagOfTokensScore(tokens: IntArray, power: Int): Int = tokens.sorted().let { t -> generateSequence(listOf(0, t.size - 1, power, 0, 0)) { (lo, hi, pw, sc, best) -> if (lo > hi) null else if (pw >= t[lo]) listOf(lo + 1, hi, pw - t[lo], sc + 1, maxOf(best, sc + 1)) else if (sc > 0) listOf(lo, hi - 1, pw + t[hi], sc - 1, best) else null }.last()[4] } }